#include <cstdio>
#include <cstdlib>
#include <string>
#include <algorithm>
int main(int argc, char** argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s N\n", argv[0]); return 1; }
    long n = atol(argv[1]);
    unsigned __int128 a = 1, b = 1;
    for (long i = 0; i < n; i++) { unsigned __int128 t = a + b; a = b; b = t; }
    std::string s;
    if (a == 0) s = "0";
    while (a > 0) { s.push_back(char('0' + (int)(a % 10))); a /= 10; }
    std::reverse(s.begin(), s.end());
    printf("%s\n", s.c_str());
    return 0;
}
